<?php
declare(strict_types=1);
namespace Hostider\Services;
use Hostider\Core\{Config,Id};use Hostider\Core\Database\Database;use Hostider\Core\Http\HttpError;use Hostider\Core\Security\{Crypto,Principal};use Hostider\Providers\Contract\Operation;use Hostider\Providers\Mock\DurableCpanel;
final readonly class ActionWorker
{
    public function __construct(private Database $db,private Config $config){}
    public function once(string $id,Principal $actor,string $scenario='SUCCESS'): bool
    {
        if($this->config->environment!=='test'||$actor->impersonating){throw new HttpError(403,'F3_TEST_ONLY');}$repository=new Repository($this->db,$this->config);$trace=Id::uuid();
        $claim=$this->db->transaction(function()use($id,$repository): ?array{
            $identity=$this->db->execute("SELECT service_id FROM svc_operations WHERE id=? AND kind IN ('SUSPEND','UNSUSPEND','TERMINATE','CHANGE_PACKAGE')",[$id])->fetchColumn();if(!$identity){return null;}$service=$repository->find($identity);$op=$this->db->execute('SELECT * FROM svc_operations WHERE id=? FOR UPDATE',[$id])->fetch();if($op['status']!=='PENDING'){return null;}if($service['current_operation_id']!==$id){throw new HttpError(409,'SERVICE_ACTION_CONFLICT');}
            $provider=$this->db->execute('SELECT * FROM svc_provider_operations WHERE lifecycle_operation_id=? FOR UPDATE',[$id])->fetch();$key=base64_decode($this->config->key,true);$json=(new Crypto($key))->decrypt($provider['request_encrypted'],'svc-operation:'.$provider['id']);if(!hash_equals($provider['request_fingerprint'],hash_hmac('sha256',$json,$key))){throw new HttpError(409,'ACTION_REQUEST_INTEGRITY');}$request=json_decode($json,true,32,JSON_THROW_ON_ERROR);$expected=$op['kind']==='TERMINATE'?'TERMINATING':$request['expected_status'];if($service['status']!==$expected){throw new HttpError(409,'SERVICE_ACTION_STATE_CHANGED');}if($op['kind']==='CHANGE_PACKAGE'){(new PackageChanges($this->db,$this->config))->verifyPayment($request['package_change_id'],$service['customer_id']);}$token=Id::uuid();
            $this->db->execute("UPDATE svc_operations SET status='RUNNING',lease_token=?,lease_until=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 60 SECOND),updated_at=UTC_TIMESTAMP(6) WHERE id=?",[$token,$id]);$this->db->execute("UPDATE svc_provider_operations SET status='RUNNING' WHERE lifecycle_operation_id=?",[$id]);$this->db->execute("INSERT INTO svc_attempt_events(operation_id,lease_token,kind,safe_code) VALUES (?,?,'STARTED','ACTION_DISPATCH_CLAIMED')",[$id,$token]);return compact('provider','request','token');
        });if(!$claim){return false;}
        try{
            $request=$claim['request'];$provider=$claim['provider'];$adapter=new DurableCpanel($this->db,$this->config,$provider['server_id'],$scenario);$method=$request['method'];$result=$adapter->$method(new Operation($provider['id'],$method,$request['resource_id'],$request['provider_config']??[]));$proof=null;
            if($result->status==='SUCCESS'&&$result->externalResourceId!==null){$inspect=$adapter->inspectAccount(new Operation(Id::uuid(),'inspectAccount',$result->externalResourceId));if($inspect->status==='SUCCESS'){$proof=$adapter->evidence($result->externalResourceId);}}
            if($result->status==='UNKNOWN'){(new Engine($this->db,$this->config))->markUnknown($id,$claim['token'],$actor,$trace);return true;}
            $this->db->transaction(function()use($id,$claim,$request,$provider,$result,$proof,$repository,$actor,$trace): void{
                $service=$repository->find($request['service_id']);$op=$this->db->execute('SELECT *,lease_until>UTC_TIMESTAMP(6) AS live FROM svc_operations WHERE id=? FOR UPDATE',[$id])->fetch();if($op['status']!=='RUNNING'||!$op['live']||!hash_equals($op['lease_token'],$claim['token'])||$service['current_operation_id']!==$id){throw new HttpError(409,'STALE_SERVICE_LEASE');}$target=match($op['kind']){'SUSPEND'=>'SUSPENDED','UNSUSPEND'=>'ACTIVE','TERMINATE'=>'TERMINATED','CHANGE_PACKAGE'=>$request['expected_status'],default=>throw new \LogicException('Unexpected service action kind')};$success=$result->status==='SUCCESS';
                if($result->operationId!==$provider['id']||$result->environment!=='mock'||$result->provider!=='cpanel'||($success&&(!$proof||$proof['id']!==$request['resource_id']||$proof['server_id']!==$provider['server_id']||$proof['service_id']!==$service['id']||$proof['status']!==$target||($op['kind']==='CHANGE_PACKAGE'&&$proof['package_name']!==$request['provider_config']['package_name'])))){throw new HttpError(409,'ACTION_INSPECT_MISMATCH');}
                $key=base64_decode($this->config->key,true);$json=\Hostider\Core\CanonicalJson::encode(['result'=>$result->jsonSerialize(),'proof'=>$proof]);$this->db->execute('INSERT INTO svc_action_evidence(operation_id,evidence_encrypted,fingerprint) VALUES (?,?,?)',[$id,(new Crypto($key))->encrypt($json,'svc-action:'.$id),hash_hmac('sha256',$json,$key)]);
                $this->db->execute('UPDATE svc_operations SET status=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?',[$success?'SUCCEEDED':'FAILED',$id]);$this->db->execute('UPDATE svc_provider_operations SET status=? WHERE id=?',[$success?'SUCCEEDED':'FAILED',$provider['id']]);$this->db->execute("INSERT INTO svc_attempt_events(operation_id,lease_token,kind,safe_code) VALUES (?,?,'FINISHED',?)",[$id,$claim['token'],$success?'ACTION_INSPECT_VERIFIED':'ACTION_DEFINITIVE_FAILURE']);
                if($op['kind']==='CHANGE_PACKAGE'){(new PackageChanges($this->db,$this->config))->complete($service,$request['package_change_id'],$success);}
                if($success){if($target!==$service['status']){$repository->transition($service,$target,$actor,$trace);}else{$repository->event($service,'PACKAGE_CHANGE_VERIFIED',$actor,$trace);}if($target==='TERMINATED'){$this->db->execute("UPDATE svc_cancellations SET status='EXECUTED' WHERE service_id=? AND status='PENDING'",[$service['id']]);$this->db->execute('UPDATE svc_services SET cancel_at=NULL WHERE id=?',[$service['id']]);(new \Hostider\Hosting\Pools($this->db,$this->config))->releaseTerminatedService($service['id']);}}
                elseif($op['kind']==='TERMINATE'){$repository->transition($service,'FAILED',$actor,$trace);}else{$repository->event($service,'ACTION_FAILED',$actor,$trace);}$this->db->execute('UPDATE svc_services SET current_operation_id=NULL,version=version+1 WHERE id=?',[$service['id']]);
            });
        }catch(\Throwable $e){try{(new Engine($this->db,$this->config))->markUnknown($id,$claim['token'],$actor,$trace);}catch(\Throwable){}throw $e;}return true;
    }
}
